import datetime
import time

class TimeUtils:

    TIME_FORMAT = "%H:%M:%S"
    DATE_FORMAT = "%Y-%m-%d"
    DATETIME_FORMAT = "%Y-%m-%d %H:%M:%S"
    SECONDS_PER_MINUTE = 60

    def __init__(self):
        self._current_datetime = datetime.datetime.now()

    def get_current_time(self):
        return self._current_datetime.strftime(self.TIME_FORMAT)

    def get_current_date(self):
        return self._current_datetime.strftime(self.DATE_FORMAT)

    def add_seconds(self, seconds):
        new_datetime = self._current_datetime + datetime.timedelta(seconds=seconds)
        return new_datetime.strftime(self.TIME_FORMAT)

    def string_to_datetime(self, string):
        return datetime.datetime.strptime(string, self.DATETIME_FORMAT)

    def datetime_to_string(self, dt):
        return dt.strftime(self.DATETIME_FORMAT)

    def get_minutes(self, string_time1, string_time2):
        time1 = self.string_to_datetime(string_time1)
        time2 = self.string_to_datetime(string_time2)
        return round((time2 - time1).seconds / self.SECONDS_PER_MINUTE)

    def get_format_time(self, year, month, day, hour, minute, second):
        time_item = datetime.datetime(year, month, day, hour, minute, second)
        return time_item.strftime(self.DATETIME_FORMAT)
